648: /// Shortest call path (Amendment 13): does `from` reach `to` through resolved
649: /// call edges, and via which call sites? Forward direction only (reverse
650: /// question = swap arguments, OQ5). Pinned determinism: multi-edges dedup to
651: /// the smallest `site_line`, neighbors expand in
652: /// `ORDER BY ds.qualname, df.path, e.site_line`, FIFO frontier with
653: /// visited-on-enqueue, parent = first discoverer. No limit surface: a single
654: /// shortest chain has at most `depth` hops (recorded deviation). Output:
655: /// caveat header, hop call-site pointers in path order, final chain line of
656: /// resolved full qualnames. Payload-journaled (Amendment 10), `name` = the
657: /// `from` argument.
658: pub fn path(
659:     conn: &Connection,
660:     root: &Path,
661:     from: &str,
662:     to: &str,
663:     depth: usize,
664: ) -> Result<Vec<String>> {
665:     let depth = depth.clamp(1, 10);
666:     let (from_ids, from_cands) = target_ids(conn, from)?;
667:     if from_ids.is_empty() {
668:         return Err(KgError::NoResults(format!("symbol '{from}' not in index")));
669:     }
670:     if from_cands.len() > 1 {
671:         return Err(KgError::Ambiguous {
672:             name: from.to_string(),
673:             total: from_ids.len(),
674:             candidates: from_cands,
675:             role: Some("from"),
676:         });
677:     }
678:     let (to_ids, to_cands) = target_ids(conn, to)?;
679:     if to_ids.is_empty() {
680:         return Err(KgError::NoResults(format!("symbol '{to}' not in index")));
681:     }
682:     if to_cands.len() > 1 {
683:         return Err(KgError::Ambiguous {
684:             name: to.to_string(),
685:             total: to_ids.len(),
686:             candidates: to_cands,
687:             role: Some("to"),
688:         });
689:     }
690:     let from_id = from_ids[0];
691:     let to_id = to_ids[0];
692:     let from_qn = from_cands[0].2.clone();
693:     let to_qn = to_cands[0].2.clone();
694:     if from_id == to_id {
695:         return Err(KgError::NoResults(format!(
696:             "'{from_qn}' and '{to_qn}' resolve to the same symbol"
697:         )));
698:     }
699:     let (chain_ids, hop_sites) = match path_bfs(conn, from_id, to_id, depth)? {
700:         PathSearch::Exhausted => {
701:             return Err(KgError::NoResults(format!(
702:                 "no call path from '{from_qn}' to '{to_qn}' at any depth <= {depth} (resolved edges only)"
703:             )));
704:         }
705:         PathSearch::CapTruncated => {
706:             return Err(KgError::NoResults(format!(
707:                 "no call path from '{from_qn}' to '{to_qn}' within depth {depth}; a longer path may exist (resolved edges only)"
708:             )));
709:         }
710:         PathSearch::Found {
711:             chain_ids,
712:             hop_sites,
713:         } => (chain_ids, hop_sites),
714:     };
715:     let hops = hop_sites.len();
716:     // One batched lookup for the chain qualnames (final line) and the hop
717:     // caller files (pointer lines: the call site lives in the caller's file).
718:     let placeholders = chain_ids.iter().map(|_| "?").collect::<Vec<_>>().join(",");
719:     let sql = format!(
720:         "SELECT s.id, s.qualname, f.path
721:          FROM symbols s JOIN files f ON f.id = s.file_id
722:          WHERE s.id IN ({placeholders})"
723:     );
724:     let mut stmt = conn.prepare(&sql)?;
725:     let params: Vec<rusqlite::types::Value> = chain_ids
726:         .iter()
727:         .map(|i| rusqlite::types::Value::from(*i))
728:         .collect();
729:     let mut qn: std::collections::HashMap<i64, String> = Default::default();
730:     let mut file: std::collections::HashMap<i64, String> = Default::default();
731:     let rows = stmt.query_map(rusqlite::params_from_iter(params.iter()), |r| {
732:         Ok((
733:             r.get::<_, i64>(0)?,
734:             r.get::<_, String>(1)?,
735:             r.get::<_, String>(2)?,
736:         ))
737:     })?;
738:     for r in rows {
739:         let (id, qualname, fpath) = r?;
740:         qn.insert(id, qualname);
741:         file.insert(id, fpath);
742:     }
743:     let mut pointers: Vec<String> = Vec::with_capacity(hops);
744:     let mut hop_files: BTreeSet<String> = BTreeSet::new();
745:     for (i, &site) in hop_sites.iter().enumerate() {
746:         let caller = chain_ids[i];
747:         let Some(f) = file.get(&caller) else {
748:             return Err(KgError::Internal("path hop file missing".to_string()));
749:         };
750:         pointers.push(format!("{f}:{site}"));
751:         hop_files.insert(f.clone());
752:     }
753:     let n_files = hop_files.len();
754:     let mut changed = 0usize;
755:     for f in &hop_files {
756:         if file_changed(conn, root, f) {
757:             changed += 1;
758:         }
759:     }
760:     let stale = changed > 0;
761:     // Payload capture (Amendment 10a): hop pointer text, byte-identical to
762:     // the stdout data lines; `name` = the `from` argument. `shown` = `total`
763:     // = hop count (no cap surface exists).
764:     let built_at = db::meta_get(conn, "built_at")
765:         .and_then(|v| v.parse().ok())
766:         .unwrap_or(0);
767:     let source_rev = db::meta_get(conn, "source_rev").unwrap_or_default();
768:     crate::journal::record_payload(from, &pointers, stale, hops, hops, built_at, &source_rev);
769:     crate::journal::record_result(hops, hops, hops, stale, 0);
770:     let mut out = Vec::with_capacity(hops + 4);
771:     out.push(PATH_CAVEAT.to_string());
772:     if stale {
773:         out.push(format!(
774:             "kg: {changed} of {n_files} result files changed since build — run kg build"
775:         ));
776:     }
777:     out.extend(pointers);
778:     let mut chain_names: Vec<&str> = Vec::with_capacity(chain_ids.len());
779:     for id in &chain_ids {
780:         let Some(q) = qn.get(id) else {
781:             return Err(KgError::Internal("path chain qualname missing".to_string()));
782:         };
783:         chain_names.push(q.as_str());
784:     }
785:     out.push(format!(
786:         "kg: chain {} ({hops} hops)",
787:         chain_names.join(" -> ")
788:     ));
789:     Ok(out)
790: }
