1081: fn parse_edge_kinds(spec: &str) -> Result<Vec<&'static str>> {
1082:     let mut out: Vec<&'static str> = Vec::new();
1083:     let mut saw_all = false;
1084:     for raw in spec.split(',') {
1085:         let part = raw.trim();
1086:         match part {
1087:             "calls" => out.push("calls"),
1088:             "imports" => out.push("imports"),
1089:             "inherits" => out.push("inherits"),
1090:             "all" => {
1091:                 saw_all = true;
1092:                 out.extend(["calls", "imports", "inherits"]);
1093:             }
1094:             "" => {
1095:                 return Err(KgError::Usage(
1096:                     "--edges requires calls,imports,inherits,all".to_string(),
1097:                 ))
