400: pub fn callers(conn: &Connection, root: &Path, name: &str, limit: usize) -> Result<QueryOutput> {
401:     let limit = clamp_limit(limit)?;
402:     let (ids, cands) = target_ids(conn, name)?;
403:     if ids.is_empty() {
404:         return Err(KgError::NoResults(format!("symbol '{name}' not in index")));
405:     }
406:     if cands.len() > 1 {
407:         // CUJ4: no merged-silent result; name the Class.method form. The
408:         // candidate list travels IN the error so non-CLI surfaces render it.
409:         return Err(KgError::Ambiguous {
410:             name: name.to_string(),
411:             total: ids.len(),
412:             candidates: cands,
413:             role: None,
414:         });
415:     }
416:     let placeholders = ids.iter().map(|_| "?").collect::<Vec<_>>().join(",");
417:     let count_sql = format!(
418:         "SELECT COUNT(*) FROM edges e WHERE e.dst_id IN ({placeholders}) AND e.kind = 'calls'"
419:     );
420:     let count_params: Vec<rusqlite::types::Value> = ids
421:         .iter()
422:         .map(|i| rusqlite::types::Value::from(*i))
423:         .collect();
424:     let total: usize = conn.query_row(
425:         &count_sql,
426:         rusqlite::params_from_iter(count_params.iter()),
427:         |r| r.get::<_, i64>(0),
428:     )? as usize;
429:     let sql = format!(
430:         "SELECT e.site_line, e.confidence, f.path, s.qualname
431:          FROM edges e
432:          JOIN symbols s ON s.id = e.src_id
433:          JOIN files f ON f.id = s.file_id
434:          WHERE e.dst_id IN ({placeholders}) AND e.kind = 'calls'
435:          ORDER BY f.path, e.site_line LIMIT {limit}"
436:     );
437:     let mut stmt = conn.prepare(&sql)?;
438:     let params: Vec<rusqlite::types::Value> = ids
439:         .iter()
440:         .map(|i| rusqlite::types::Value::from(*i))
441:         .collect();
442:     let rows = stmt.query_map(rusqlite::params_from_iter(params.iter()), |r| {
443:         let site: i64 = r.get(0)?;
444:         let conf: String = r.get(1)?;
445:         let path: String = r.get(2)?;
446:         Ok(Pointer {
447:             file: path,
448:             line: site,
449:             tag: if conf == "AMBIGUOUS" {
450:                 " [ambiguous]"
451:             } else {
452:                 ""
453:             },
454:             detail: r.get::<_, String>(3)?,
455:         })
456:     })?;
457:     collect_output(
458:         conn,
459:         root,
460:         name,
461:         rows,
462:         limit,
463:         "0 callers found (dynamic dispatch possible — grep fallback recommended)",
464:         Some(total),
465:     )
466: }
