1081: fn parse_edge_kinds(spec: &str) -> Result<Vec<&'static str>> {
1082:     let mut out: Vec<&'static str> = Vec::new();
1083:     let mut saw_all = false;
1084:     for raw in spec.split(',') {
1085:         let part = raw.trim();
1086:         match part {
1087:             "calls" => out.push("calls"),
1088:             "imports" => out.push("imports"),
1089:             "inherits" => out.push("inherits"),
1090:             "all" => {
1091:                 saw_all = true;
1092:                 out.extend(["calls", "imports", "inherits"]);
1093:             }
1094:             "" => {
1095:                 return Err(KgError::Usage(
1096:                     "--edges requires calls,imports,inherits,all".to_string(),
1097:                 ))
1098:             }
1099:             other => {
1100:                 return Err(KgError::Usage(format!(
1101:                     "unknown --edges value '{other}' (calls,imports,inherits,all)"
1102:                 )))
1103:             }
1104:         }
1105:     }
1106:     if saw_all && spec.split(',').any(|p| p.trim() != "all") {
1107:         return Err(KgError::Usage(
1108:             "--edges all cannot be combined with explicit kinds".to_string(),
1109:         ));
1110:     }
1111:     out.sort_unstable();
1112:     out.dedup();
1113:     if out.is_empty() {
1114:         return Err(KgError::Usage(
1115:             "--edges requires at least one kind".to_string(),
1116:         ));
1117:     }
1118:     Ok(out)
1119: }
