1125: pub fn validate_path_scope(path: &str, allow_root: bool) -> Result<()> {
1126:     let p = path.trim().trim_start_matches("./").trim_end_matches('/');
1127:     let bad_component = !p.is_empty()
1128:         && p.split('/')
1129:             .any(|seg| seg.is_empty() || seg == "." || seg == "..");
1130:     if (!allow_root && (p.is_empty() || p == "."))
1131:         || bad_component
1132:         || p.starts_with('/')
1133:         || p.contains('\\')
1134:     {
1135:         return Err(KgError::Usage(format!(
1136:             "invalid scope '{path}' (repo-relative path required)"
1137:         )));
1138:     }
1139:     Ok(())
1140: }
