1146: fn path_scope_sql(alias: &str, path: Option<&str>) -> String {
1147:     match path {
1148:         None => String::new(),
1149:         Some(path) => {
1150:             let escaped = path
1151:                 .trim_start_matches("./")
1152:                 .trim_end_matches('/')
1153:                 .replace('\'', "''");
1154:             format!(
1155:                 " AND ({alias}.path = '{escaped}' OR substr({alias}.path, 1, length('{escaped}') + 1) = '{escaped}' || '/')"
1156:             )
1157:         }
1158:     }
1159: }
