1184: fn impact_detail(
1185:     context: bool,
1186:     qualname: &str,
1187:     src_kind: &str,
1188:     explain: bool,
1189:     kind: &str,
1190:     depth: usize,
1191: ) -> String {
1192:     let mut parts = Vec::new();
1193:     if context && !qualname.is_empty() && matches!(src_kind, "function" | "method") {
1194:         parts.push(format!("[in {qualname}]"));
1195:     }
1196:     if explain {
1197:         parts.push(format!("[{kind} depth={depth}]"));
1198:     }
1199:     parts.join(" ")
