1206:         (true, true) => "0 impacting files found (unresolved imports/bases are omitted)",
1207:         (true, false) => "0 impacting files found (unresolved imports are omitted)",
1208:         (false, true) => "0 impacting files found (unresolved bases are omitted)",
1209:         (false, false) => "0 impacting files found",
