1214: #[allow(clippy::too_many_arguments)] // CLI surface; a params struct adds no value here.
1215: pub fn impact(
1216:     conn: &Connection,
1217:     root: &Path,
1218:     file: &str,
1219:     limit: usize,
1220:     sites: bool,
1221:     depth: usize,
1222:     edges: &str,
1223:     context: bool,
1224:     explain: bool,
1225: ) -> Result<QueryOutput> {
1226:     let limit = clamp_limit(limit)?;
1227:     let depth = depth.clamp(1, 10);
1228:     let kinds = parse_edge_kinds(edges)?;
1229:     let kind_sql = edge_kind_sql(&kinds);
1230:     let site_key = IMPACT_SITE_KEY;
1231:     let rel = file.trim_start_matches("./").to_string();
1232:     let exists: bool = conn
1233:         .query_row("SELECT COUNT(*) FROM files WHERE path = ?1", [&rel], |r| {
1234:             r.get(0)
1235:         })
1236:         .map(|c: i64| c > 0)?;
1237:     if !exists {
1238:         return Err(KgError::NoResults(format!("path '{file}' not indexed")));
1239:     }
1240:     let extended = depth > 1 || context || kinds.iter().any(|k| *k != "calls");
1241:     let caveat = if extended {
1242:         if kinds.iter().any(|k| *k != "calls") {
1243:             IMPACT_EDGES_CAVEAT
1244:         } else {
1245:             IMPACT_CALLS_CAVEAT
1246:         }
1247:     } else {
1248:         ""
1249:     };
1250:     // Grouped mode cannot carry a meaningful per-edge tag; --context and
1251:     // --explain switch to per-site rows at depth 1.
1252:     let sites = sites || (depth == 1 && (context || explain));
1253:     if depth > 1 && sites {
1254:         return Err(KgError::Usage(
1255:             "--sites is only valid with --depth 1".to_string(),
1256:         ));
1257:     }
1258: 
1259:     if depth == 1 {
1260:         if !sites {
1261:             let total_files: usize = conn.query_row(
1262:                 &format!(
1263:                     "SELECT COUNT(DISTINCT sf.path) FROM edges e
1264:                      JOIN symbols ds ON ds.id = e.dst_id JOIN files df ON df.id = ds.file_id
1265:                      JOIN symbols ss ON ss.id = e.src_id JOIN files sf ON sf.id = ss.file_id
1266:                      WHERE df.path = ?1 AND e.kind IN ({kind_sql})"
1267:                 ),
1268:                 [&rel],
1269:                 |r| r.get::<_, i64>(0),
1270:             )? as usize;
1271:             if total_files == 0 {
1272:                 if extended {
1273:                     return Err(KgError::NoResultsCaveated {
1274:                         caveat,
1275:                         detail: {
1276:                             let has_imports = kinds.contains(&"imports");
1277:                             let has_inherits = kinds.contains(&"inherits");
1278:                             match (has_imports, has_inherits) {
1279:                                 (true, true) => {
1280:                                     "0 impacting files found (unresolved imports/bases are omitted)"
1281:                                 }
1282:                                 (true, false) => {
1283:                                     "0 impacting files found (unresolved imports are omitted)"
1284:                                 }
1285:                                 (false, true) => {
1286:                                     "0 impacting files found (unresolved bases are omitted)"
1287:                                 }
1288:                                 (false, false) => "0 impacting files found",
1289:                             }
1290:                             .to_string()
1291:                         },
1292:                     });
1293:                 }
1294:                 return Err(KgError::NoResults("0 impacting files found".to_string()));
1295:             }
1296:             let mut stmt = conn.prepare(&format!(
1297:                 "SELECT sf.path, MIN(e.site_line) AS line,
1298:                         COUNT(DISTINCT {site_key}) AS n
1299:                  FROM edges e
1300:                  JOIN symbols ds ON ds.id = e.dst_id JOIN files df ON df.id = ds.file_id
1301:                  JOIN symbols ss ON ss.id = e.src_id JOIN files sf ON sf.id = ss.file_id
1302:                  WHERE df.path = ?1 AND e.kind IN ({kind_sql})
1303:                  GROUP BY sf.path ORDER BY sf.path LIMIT {limit}"
1304:             ))?;
1305:             let rows = stmt.query_map([&rel], |r| {
1306:                 Ok(Pointer {
1307:                     file: r.get::<_, String>(0)?,
1308:                     line: r.get::<_, i64>(1)?,
1309:                     tag: "",
1310:                     detail: format!("({} sites)", r.get::<_, i64>(2)?),
1311:                 })
1312:             })?;
1313:             let mut out = collect_output(
1314:                 conn,
1315:                 root,
1316:                 &rel,
1317:                 rows,
1318:                 limit,
1319:                 "0 impacting files found",
1320:                 Some(total_files),
1321:             )?;
1322:             if extended {
1323:                 out.header = Some(match out.header.take() {
1324:                     Some(stale) => format!("{caveat}\n{stale}"),
1325:                     None => caveat.to_string(),
1326:                 });
1327:             }
1328:             return Ok(out);
1329:         }
1330: 
1331:         let total: usize = conn.query_row(
1332:             &format!(
1333:                 "SELECT COUNT(DISTINCT {site_key}) FROM edges e
1334:                  JOIN symbols ds ON ds.id = e.dst_id JOIN files df ON df.id = ds.file_id
1335:                  JOIN symbols ss ON ss.id = e.src_id
1336:                  WHERE df.path = ?1 AND e.kind IN ({kind_sql})"
1337:             ),
1338:             [&rel],
1339:             |r| r.get::<_, i64>(0),
1340:         )? as usize;
1341:         if total == 0 {
1342:             if extended {
1343:                 return Err(KgError::NoResultsCaveated {
1344:                     caveat,
1345:                     detail: impact_empty_detail(&kinds),
1346:                 });
1347:             }
1348:             return Err(KgError::NoResults("0 impacting files found".to_string()));
1349:         }
1350:         let sql = format!(
1351:             "SELECT MIN(e.site_line), MIN(e.confidence), MIN(sf.path),
1352:                     MIN(ss.qualname), MIN(ss.kind), MIN(e.kind)
1353:              FROM edges e
1354:              JOIN symbols ds ON ds.id = e.dst_id JOIN files df ON df.id = ds.file_id
1355:              JOIN symbols ss ON ss.id = e.src_id JOIN files sf ON sf.id = ss.file_id
1356:              WHERE df.path = ?1 AND e.kind IN ({kind_sql})
